SELECT jsonb_build_object('read13_marker','RuntimeEffectReceipt/field'::text,'position','BEFORE'::text);
SELECT jsonb_build_object('model','CustomerProfile','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,user_id,status,revision,privacy_generation,display_name,avatar_media_id,city,country,created_at,updated_at,archived_at,state,mutation_transaction_id FROM app.customer_profiles WHERE id IN ('76b7a107-ed42-5471-9d24-946e10c38a4f'::uuid)) observed;
SELECT jsonb_build_object('model','RuntimeCommandReceipt','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,owner_module_id,operation,subject_scope,semantic_key,fingerprint,state,source_revision,result_schema_id,result_schema_version,result_digest,result_body,created_at,mutation_transaction_id FROM platform.runtime_command_receipt WHERE id IN ('741de8ba-6738-5525-9fa3-b78427b89c34'::uuid)) observed;
SELECT jsonb_build_object('model','RuntimeEffectReceipt','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,command_receipt_id,owner_module_id,operation,subject_scope,semantic_effect_key,fingerprint,state,source_revision,fence,result_schema_id,result_hash,committed_at,created_at,mutation_transaction_id FROM platform.runtime_effect_receipt WHERE id IN ('e37fe5e1-86af-5390-a9b3-bcbc1b38c7f2'::uuid,'6fe8df3b-8977-540b-910c-a9b1476a180f'::uuid)) observed;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT jsonb_build_object('read13_marker','RuntimeEffectReceipt/field'::text,'position','AFTER'::text);
